# regstar.py -- shared exact code for the regular stars census (study 2026-11-09-regular-stars-census).
# Exact arithmetic in Q(sqrt5) (Q5 of q5.py, copied from studies/2026-11-09-turn-theorem); any dimension d.
#
# 1. Mirrors and flags. The symmetry group G of a regular polytope is generated by reflections. Its mirrors are found exactly from
#    the corner set (a difference v - w whose reflection maps the corner set onto itself). A regular polytope (convex or star) with
#    symmetry group in G is a chain of mirrors m_0, ..., m_{d-1} (m_i perpendicular to m_j when |i - j| >= 2) together with its flag
#    q_0 (corner), q_1 (edge midpoint), ..., q_{d-1} (facet centre): q_0 spans the line fixed by m_1..m_{d-1}, and q_{k+1} is the
#    orthogonal projection of q_k onto the line fixed by all mirrors but m_{k+1} (Coxeter's Wythoff construction; the flag Gram
#    identity q_j.q_k = rho^2_max(j,k) follows). The angle between m_i and m_{i+1} gives the Schlafli symbol: cos^2 = 1/4 -> 3,
#    1/2 -> 4, (3+sqrt5)/8 -> 5, (3-sqrt5)/8 -> 5/2.
# 2. The flag line of a regular polytope (convex or star):
#       Delta(mu) = conv(0, q_0, ..., q_{d-1}) cut by q_0.x <= mu,   S*(mu) = G . Delta(mu),   h^2 <= mu <= R^2,
#    and the flag-wise antipol Delta^v(mu) = {y in the flag cone : q_{d-1}.y <= 1, q_0.y <= R^2/mu} = h^-2 Delta(c/mu), c = h^2 R^2.
#    For a convex regular P the flag simplex is a chamber of G, and S*(mu) = P ∩ mu P* is the polar line of the turn theorem.
#    t_min*(mu) = max { x.y : x in S*(mu), y in S*^v(mu) } = max over corner pairs (a, b) of Delta, Delta^v of a+ . b+, where x+ is
#    the image of x in the closed fundamental chamber of G (dominance lemma: max_g x.(g y) = x+ . y+).
import itertools
from fractions import Fraction as Fr
import numpy as np
from q5 import Q5, PHI, IPHI, ZERO, ONE

def Z(x): return x if isinstance(x, Q5) else Q5(x)
def dotv(u, v):
    s = ZERO
    for a, b in zip(u, v): s = s + a * b
    return s
def addv(u, v): return tuple(a + b for a, b in zip(u, v))
def subv(u, v): return tuple(a - b for a, b in zip(u, v))
def scal(k, v): k = Z(k); return tuple(k * x for x in v)
def flv(v): return np.array([x.f() for x in v])
def iszero(v): return all(x == ZERO for x in v)
def refl(m, x): return subv(x, scal(Z(2) * dotv(x, m) / dotv(m, m), m))
def key(v): return tuple((x.a, x.b) for x in v)

def det(M):
    M = [list(r) for r in M]; n = len(M); s = ONE
    for c in range(n):
        p = next((r for r in range(c, n) if not (M[r][c] == ZERO)), None)
        if p is None: return ZERO
        if p != c: M[c], M[p] = M[p], M[c]; s = -s
        s = s * M[c][c]; inv = M[c][c].inv()
        for r in range(c + 1, n):
            if not (M[r][c] == ZERO):
                f = M[r][c] * inv; M[r] = [a - f * b for a, b in zip(M[r], M[c])]
    return s

def perp(vs, d):
    """a vector perpendicular to the d-1 vectors vs (generalised cross product); zero if they are dependent"""
    out = []
    for i in range(d):
        minor = [[v[j] for j in range(d) if j != i] for v in vs]
        out.append(det(minor) * (ONE if i % 2 == 0 else -ONE))
    return tuple(out)

def parallel(u, v):
    """u = k v with k > 0 (exact)"""
    i = next(j for j in range(len(v)) if not (v[j] == ZERO))
    k = u[i] / v[i]
    return k.sign() > 0 and all(u[j] == k * v[j] for j in range(len(v)))

def same_line(u, v):
    i = next(j for j in range(len(v)) if not (v[j] == ZERO))
    k = u[i] / v[i]
    return all(u[j] == k * v[j] for j in range(len(v)))

def mirrors_of(V, tol=1e-9):
    """exact mirror normals (one per mirror) of the symmetry group of the corner set V: differences v - w whose reflection maps V
    onto V (checked in floats, then exactly)"""
    F = np.array([flv(v) for v in V]); Vset = {key(v) for v in V}
    out = []; dirs = []
    for i, j in itertools.combinations(range(len(V)), 2):
        m = subv(V[i], V[j]); mf = flv(m); mf_n = mf / np.linalg.norm(mf)
        if any(abs(abs(mf_n @ u) - 1) < 1e-9 for u in dirs): continue
        R = F - 2 * np.outer(F @ mf, mf) / (mf @ mf)
        D = np.abs(R[:, None, :] - F[None, :, :]).max(2).min(1)
        if D.max() > 1e-7: continue
        assert all(key(refl(m, v)) in Vset for v in V), 'float mirror is not exact'
        out.append(m); dirs.append(mf_n)
    return out

SYM = {(Fr(0), Fr(0)): '2', (Fr(1, 4), Fr(0)): '3', (Fr(1, 2), Fr(0)): '4', (Fr(3, 8), Fr(1, 8)): '5', (Fr(3, 8), Fr(-1, 8)): '5/2',
       (Fr(3, 4), Fr(0)): '6'}
def mirror_angle(a, b):
    c2 = dotv(a, b) * dotv(a, b) / (dotv(a, a) * dotv(b, b))
    return SYM.get((c2.a, c2.b), 'other')

def flag_from_mirrors(ms, d):
    """flag q_0..q_{d-1} of the Wythoff chain ms (exact); None if degenerate"""
    L = [perp([ms[j] for j in range(d) if j != k], d) for k in range(d)]
    if any(iszero(l) for l in L): return None
    q = [L[0]]
    for k in range(1, d):
        p = q[-1]; l = L[k]
        q.append(scal(dotv(p, l) / dotv(l, l), l))
        if iszero(q[-1]): return None
    return q

def enumerate_chains(M, d, starts=(0,)):
    """all mirror chains m_0..m_{d-1} from the mirror list M, with m_0 = M[0] fixed (G is transitive on its mirrors for the
    H3, H4; for Oh, B4, F4 every mirror is tried as m_0) and non-perpendicular neighbours, perpendicular non-neighbours"""
    out = []
    perpm = {(i, j): dotv(M[i], M[j]) == ZERO for i in range(len(M)) for j in range(len(M))}
    def rec(ch):
        if len(ch) == d: out.append(tuple(ch)); return
        for j in range(len(M)):
            if j in ch: continue
            if perpm[(ch[-1], j)]: continue
            if not all(perpm[(i, j)] for i in ch[:-1]): continue
            rec(ch + [j])
    for s0 in starts: rec([s0])
    return out

def gram_ok(q):
    r2 = [dotv(x, x) for x in q]; d = len(q)
    return all(dotv(q[j], q[k]) == r2[max(j, k)] for j in range(d) for k in range(d)), r2

# ---------- groups in floats (orders, orbits, densities) ----------
def refl_mat(m):
    mf = flv(m); return np.eye(len(mf)) - 2 * np.outer(mf, mf) / (mf @ mf)

def group_float(gens, cap=20000):
    d = gens[0].shape[0]; I = np.eye(d)
    seen = {tuple(np.round(I, 6).ravel()): I}; frontier = [I]
    while frontier:
        nxt = []
        for g in frontier:
            for s in gens:
                x = g @ s; k = tuple(np.round(x, 6).ravel())
                if k not in seen:
                    seen[k] = x; nxt.append(x)
                    if len(seen) > cap: return None
        frontier = nxt
    return list(seen.values())

def orbit_float(G, x):
    return np.unique(np.round(np.array([g @ x for g in G]), 7), axis=0)

def density(G, q, z):
    """number of chambers g.z (z generic, inside one chamber) inside the cone spanned by the flag q: the density"""
    Q = np.array([flv(x) for x in q]).T
    n = 0
    for g in G:
        c = np.linalg.solve(Q, g @ z)
        if (c > 1e-9).all(): n += 1
    return n

# ---------- folding into the fundamental chamber (exact) ----------
class Chamber:
    def __init__(self, mirrors, z):
        self.z = tuple(Z(x) for x in z)
        self.pos = [m if dotv(m, self.z).sign() > 0 else scal(-1, m) for m in mirrors]
        assert all(dotv(m, self.z).sign() != 0 for m in self.pos), 'z on a mirror'
    def fold(self, x):
        while True:
            for m in self.pos:
                if dotv(x, m).sign() < 0: x = refl(m, x); break
            else: return x
    def foldf(self, X):
        """float folding of many points (rows)"""
        P = np.array([flv(m) for m in self.pos]); X = X.copy()
        for _ in range(1000):
            S = X @ P.T; bad = S < -1e-12
            if not bad.any(): return X
            j = np.argmin(S, axis=1); rows = np.where(bad.any(1))[0]
            m = P[j[rows]]; s = S[rows, j[rows]]
            X[rows] = X[rows] - 2 * (s / (m * m).sum(1))[:, None] * m
        raise RuntimeError('fold did not end')

# ---------- the flag line ----------
def delta_vertices(q, r2, mu):
    """corners of conv(0, q_0..q_{d-1}) cut by q_0.x <= mu (q_0.q_k = r2[k])"""
    mu = Z(mu); d = len(q); out = [tuple(ZERO for _ in range(d))]
    for k in range(d):
        if r2[k] <= mu: out.append(q[k])
        else: out.append(scal(mu / r2[k], q[k]))
    for j in range(d):
        for k in range(d):
            if r2[j] > mu and r2[k] < mu:
                s = (r2[j] - mu) / (r2[j] - r2[k]); out.append(addv(q[j], scal(s, subv(q[k], q[j]))))
    uniq = {}
    for v in out: uniq[key(v)] = v
    return list(uniq.values())

def antipol_vertices(q, r2, mu):
    h2 = r2[-1]; c = h2 * r2[0]
    return [scal(ONE / h2, v) for v in delta_vertices(q, r2, c / Z(mu))]

def tmin_star(q, r2, mu, ch, fold=True):
    A = delta_vertices(q, r2, mu); B = antipol_vertices(q, r2, mu)
    if fold:
        A = [ch.fold(a) for a in A]; B = [ch.fold(b) for b in B]
    best = None; arg = None
    for a in A:
        for b in B:
            v = dotv(a, b)
            if best is None or v > best: best, arg = v, (a, b)
    return best, arg

def tmin_star_f(q, r2, mu, ch, fold=True):
    """float version (mu float)"""
    qf = [flv(x) for x in q]; rf = [x.f() for x in r2]; d = len(q)
    def dv(m):
        out = [np.zeros(d)]
        for k in range(d): out.append(qf[k] if rf[k] <= m else (m / rf[k]) * qf[k])
        for j in range(d):
            for k in range(d):
                if rf[j] > m and rf[k] < m: s = (rf[j] - m) / (rf[j] - rf[k]); out.append(qf[j] + s * (qf[k] - qf[j]))
        return np.array(out)
    h2 = rf[-1]; c = h2 * rf[0]
    A = dv(mu); B = dv(c / mu) / h2
    if fold: A = ch.foldf(A); B = ch.foldf(B)
    return float((A @ B.T).max())

# ---------- serialisation ----------
def q5s(x): return f'{x.a}' if x.b == 0 else f'{x.a} + ({x.b})*sqrt(5)'
def q5p(s):
    s = s.strip()
    if 'sqrt' not in s: return Q5(Fr(s))
    a, b = s.split(' + (', 1); return Q5(Fr(a), Fr(b.split(')')[0]))
def vs(v): return [q5s(x) for x in v]
def vp(l): return tuple(q5p(x) for x in l)
